### Phase 2: The Backend (Node.js & Express)

We will create an API that serves JSON data.

1.  **Initialize the server:**
    ```bash
    cd server
    npm init -y
    npm install express cors nodemon
    ```
    *`cors` is needed to allow React to talk to Node.*

2.  **Create `server.js`:**
    Create a file named `server.js` inside the `server` folder.

    ```javascript
    const express = require('express');
    const cors = require('cors');
    const app = express();
    const PORT = 5000;

    // Middleware
    app.use(cors());
    app.use(express.json()); // To parse JSON bodies

    // DUMMY DATA
    let users = [
        { id: 1, name: 'John Doe', email: 'john@example.com', role: 'Admin' },
        { id: 2, name: 'Jane Smith', email: 'jane@example.com', role: 'User' },
        { id: 3, name: 'Alice Wonder', email: 'alice@example.com', role: 'Editor' }
    ];

    // GET ALL USERS
    app.get('/api/users', (req, res) => {
        res.json(users);
    });

    // CREATE A USER
    app.post('/api/users', (req, res) => {
        const newUser = {
            id: users.length + 1,
            ...req.body
        };
        users.push(newUser);
        res.status(201).json(newUser);
    });

    // DELETE A USER
    app.delete('/api/users/:id', (req, res) => {
        const id = parseInt(req.params.id);
        users = users.filter(user => user.id !== id);
        res.json({ message: 'User deleted' });
    });

    // Start Server
    app.listen(PORT, () => {
        console.log(`Server running on http://localhost:${PORT}`);
    });
    ```

3.  **Update `package.json`:**
    Add a start script.
    ```json
    "scripts": {
      "start": "node server.js",
      "dev": "nodemon server.js"
    }
    ```
    Run the backend:
    ```bash
    npm run dev
    ```

